SELECT CASE WHEN (p.take_profit - p.entry_price) / NULLIF(p.entry_price - p.stop_loss, 0) < 0.75 THEN 'a_rr<0.75' WHEN (p.take_profit - p.entry_price) / NULLIF(p.entry_price - p.stop_loss, 0) < 1 THEN 'b_rr0.75-1' WHEN (p.take_profit - p.entry_price) / NULLIF(p.entry_price - p.stop_loss, 0) < 1.5 THEN 'c_rr1-1.5' ELSE 'd_rr>=1.5' END AS rr_band, CASE WHEN m.entry_quality_score < 55 THEN 'eq50-54' WHEN m.entry_quality_score < 70 THEN 'eq55-69' WHEN m.entry_quality_score < 85 THEN 'eq70-84' ELSE 'eq85+' END AS eq_band, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.status = 'STOPPED') AS stopped, ROUND(SUM(p.realized_pnl), 4) AS pnl, ROUND(SUM(p.entry_price * p.quantity), 2) AS notional FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') GROUP BY rr_band, eq_band ORDER BY rr_band, eq_band LIMIT 40;